{
  "name": "LP Dailyceklist dan Observasi",
  "description": "A professional Daily Checklist and Observation tool for Loss Prevention and Operations. Features AI-powered report generation and trend analysis.",
  "requestFramePermissions": [
    "camera",
    "geolocation"
  ]
}

import React, { useState, useEffect, useRef } from 'react';
import { ChecklistItem, InspectionStatus, Observation, INITIAL_CHECKLIST, DailyReport } from '../types';
import { generateReportSummary } from '../services/geminiService';
import { Save, AlertCircle, Plus, Trash2, Loader2, Wand2, Clock, Lock, Info, Camera, X, MapPin, Wifi, WifiOff } from 'lucide-react';

// KONFIGURASI LOKASI STORE (Contoh: Titik Pusat Jakarta - Silakan sesuaikan koordinat target)
const STORE_COORDS = {
  lat: -6.2088, // Ganti dengan Latitude Store Anda
  lng: 106.8456 // Ganti dengan Longitude Store Anda
};
const MAX_RADIUS_METERS = 500; // Radius toleransi (500 meter)

interface InspectionFormProps {
  onSave: (report: DailyReport) => void;
  onCancel: () => void;
  existingReports: DailyReport[];
}

type CameraTarget = { type: 'observation' } | { type: 'checklist'; itemId: string };

const InspectionForm: React.FC<InspectionFormProps> = ({ onSave, onCancel, existingReports }) => {
  const [inspectorName, setInspectorName] = useState('');
  const [nik, setNik] = useState('');
  const [nikError, setNikError] = useState<string | null>(null);
  const [shift, setShift] = useState('');
  const [items, setItems] = useState<ChecklistItem[]>(INITIAL_CHECKLIST);
  const [observations, setObservations] = useState<Observation[]>([]);
  const [newObs, setNewObs] = useState<Partial<Observation>>({ severity: 'Medium' });
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string>(INITIAL_CHECKLIST[0].category);

  // Connection & Location Status
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [locationStatus, setLocationStatus] = useState<'checking' | 'verified' | 'denied' | 'error'>('checking');
  const [distance, setDistance] = useState<number | null>(null);

  // Camera State
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [cameraTarget, setCameraTarget] = useState<CameraTarget | null>(null);
  const [tempObsImage, setTempObsImage] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  // Monitor Internet Connection
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Monitor Geolocation
  useEffect(() => {
    checkLocation();
  }, []);

  const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number) => {
    const R = 6371e3; // metres
    const φ1 = lat1 * Math.PI / 180;
    const φ2 = lat2 * Math.PI / 180;
    const Δφ = (lat2 - lat1) * Math.PI / 180;
    const Δλ = (lon2 - lon1) * Math.PI / 180;

    const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
              Math.cos(φ1) * Math.cos(φ2) *
              Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return R * c; // in metres
  };

  const checkLocation = () => {
    setLocationStatus('checking');
    if (!navigator.geolocation) {
      setLocationStatus('error');
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const d = calculateDistance(
          position.coords.latitude,
          position.coords.longitude,
          STORE_COORDS.lat,
          STORE_COORDS.lng
        );
        setDistance(Math.round(d));
        if (d <= MAX_RADIUS_METERS) {
          setLocationStatus('verified');
        } else {
          setLocationStatus('denied');
        }
      },
      (error) => {
        console.error("Location error:", error);
        setLocationStatus('error');
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  // Logic Shift PreOpening/Closing
  useEffect(() => {
    const todayStr = new Date().toDateString();
    const morningReport = existingReports.find(r => new Date(r.date).toDateString() === todayStr && r.shift === 'Pagi');
    const afternoonReport = existingReports.find(r => new Date(r.date).toDateString() === todayStr && r.shift === 'Siang');

    if (shift === 'Siang') {
      setItems(prevItems => prevItems.map(item => {
        if (item.category === 'PreOpening' && morningReport) {
          const sourceItem = morningReport.items.find(mi => mi.id === item.id);
          return sourceItem ? { ...item, status: sourceItem.status, value: sourceItem.value, photo: sourceItem.photo, comment: sourceItem.comment || '(Shift Pagi)' } : item;
        }
        return item;
      }));
    } else if (shift === 'Malam') {
      setItems(prevItems => prevItems.map(item => {
        if (item.category === 'PreOpening' && morningReport) {
          const s = morningReport.items.find(mi => mi.id === item.id);
          if (s) return { ...item, status: s.status, value: s.value, photo: s.photo, comment: s.comment || '(Shift Pagi)' };
        }
        if (item.category === 'Closing' && afternoonReport) {
          const s = afternoonReport.items.find(mi => mi.id === item.id);
          if (s) return { ...item, status: s.status, value: s.value, photo: s.photo, comment: s.comment || '(Shift Siang)' };
        }
        return item;
      }));
    }
  }, [shift, existingReports]);

  const categories = Array.from(new Set(INITIAL_CHECKLIST.map(i => i.category)));

  const handleNikChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (value === '' || /^\d+$/.test(value)) {
      setNik(value);
      if (nikError) setNikError(null);
    }
  };

  const handleStatusChange = (id: string, status: InspectionStatus) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, status } : item));
  };

  const handleValueChange = (id: string, value: string) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, value } : item));
  };

  const handleCommentChange = (id: string, comment: string) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, comment } : item));
  };

  const startCamera = async (target: CameraTarget) => {
    try {
      setCameraTarget(target);
      const mediaStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      setStream(mediaStream);
      setIsCameraOpen(true);
      setTimeout(() => { if (videoRef.current) videoRef.current.srcObject = mediaStream; }, 100);
    } catch (err) {
      alert("Tidak dapat mengakses kamera.");
    }
  };

  const stopCamera = () => {
    if (stream) stream.getTracks().forEach(track => track.stop());
    setStream(null);
    setIsCameraOpen(false);
  };

  const takePhoto = () => {
    if (videoRef.current && canvasRef.current && cameraTarget) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        const width = 640;
        const scaleFactor = width / video.videoWidth;
        const height = video.videoHeight * scaleFactor;
        canvas.width = width;
        canvas.height = height;
        context.drawImage(video, 0, 0, width, height);
        const imageData = canvas.toDataURL('image/jpeg', 0.7);
        if (cameraTarget.type === 'checklist') {
            setItems(prev => prev.map(item => item.id === cameraTarget.itemId ? { ...item, photo: imageData } : item));
        } else {
            setTempObsImage(imageData);
        }
        stopCamera();
      }
    }
  };

  const addObservation = () => {
    if (!newObs.description || !newObs.location) return;
    setObservations([...observations, {
      id: Date.now().toString(),
      description: newObs.description!,
      location: newObs.location!,
      severity: newObs.severity as any,
      timestamp: new Date().toISOString(),
      photo: tempObsImage || undefined
    }]);
    setNewObs({ severity: 'Medium', description: '', location: '' });
    setTempObsImage(null);
  };

  const calculateScore = () => {
    let scoreableItems = items.filter(i => !i.inputType || i.inputType === 'status');
    if (shift === 'Pagi') scoreableItems = scoreableItems.filter(i => i.category !== 'Closing');
    const applicableItems = scoreableItems.filter(i => i.status !== InspectionStatus.NA && i.status !== undefined);
    if (applicableItems.length === 0) return 0;
    const passed = applicableItems.filter(i => i.status === InspectionStatus.PASS).length;
    return Math.round((passed / applicableItems.length) * 100);
  };

  const handleSubmit = async () => {
    if (!isOnline) {
      alert("Koneksi internet terputus. Mohon sambungkan kembali sebelum menyimpan.");
      return;
    }
    if (locationStatus !== 'verified') {
      alert("Anda harus berada di lokasi store untuk melakukan inspeksi.");
      return;
    }
    if (!inspectorName.trim() || !nik.trim() || !shift.trim()) {
      alert("Mohon lengkapi data Shift, Anggota, dan NIK.");
      return;
    }
    if (nik.length < 6) {
      setNikError("NIK harus minimal 6 digit.");
      return;
    }

    setIsGenerating(true);
    const finalItems = items.map(item => {
      if (shift === 'Pagi' && item.category === 'Closing') {
        return { ...item, status: InspectionStatus.NA, comment: '(Otomatis N/A - Shift Pagi)' };
      }
      return item;
    });

    const reportData: DailyReport = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      inspectorName,
      nik,
      shift,
      items: finalItems,
      observations,
      complianceScore: calculateScore(),
      aiSummary: 'Sedang membuat...'
    };

    const summary = await generateReportSummary(reportData);
    reportData.aiSummary = summary;
    setIsGenerating(false);
    onSave(reportData);
  };

  const isFormDisabled = !isOnline || locationStatus !== 'verified';

  return (
    <div className="max-w-4xl mx-auto pb-24 relative">

      {/* Requirement Overlay / Banner */}
      {!isOnline && (
        <div className="mb-4 p-4 bg-red-600 text-white rounded-xl shadow-lg flex items-center gap-3 animate-pulse">
          <WifiOff size={24} />
          <div>
            <p className="font-bold">Koneksi Terputus!</p>
            <p className="text-sm">Aplikasi memerlukan akses internet aktif untuk beroperasi.</p>
          </div>
        </div>
      )}

      {locationStatus === 'denied' && (
        <div className="mb-4 p-4 bg-amber-600 text-white rounded-xl shadow-lg flex items-center gap-3">
          <MapPin size={24} />
          <div className="flex-1">
            <p className="font-bold">Di Luar Area Store!</p>
            <p className="text-sm">Anda berada sekitar {distance}m dari store. Jarak maksimal {MAX_RADIUS_METERS}m.</p>
          </div>
          <button onClick={checkLocation} className="bg-white/20 px-3 py-1 rounded text-xs font-bold hover:bg-white/30">Cek Ulang</button>
        </div>
      )}

      {isCameraOpen && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col justify-center items-center">
             <div className="relative w-full h-full max-w-md bg-black flex flex-col">
                <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover"></video>
                <canvas ref={canvasRef} className="hidden"></canvas>
                <div className="absolute bottom-0 left-0 right-0 p-6 flex justify-between items-center bg-gradient-to-t from-black/80 to-transparent">
                  <button onClick={stopCamera} className="bg-white/20 backdrop-blur-sm text-white p-3 rounded-full"><X size={24} /></button>
                  <button onClick={takePhoto} className="bg-white p-1 rounded-full border-4 border-slate-300 active:scale-95"><div className="w-16 h-16 bg-white rounded-full border-4 border-slate-900"></div></button>
                  <div className="w-12"></div>
                </div>
             </div>
        </div>
      )}

      <div className={`bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden transition-opacity ${isFormDisabled ? 'opacity-50 pointer-events-none' : 'opacity-100'}`}>
        <div className="bg-slate-800 p-6 text-white flex justify-between items-start">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2"><Wand2 className="text-blue-400" /> Inspeksi Harian</h2>
            <p className="text-slate-300 text-sm mt-1">Ceklist Loss Prevention & Operasional</p>
          </div>
          <div className="flex flex-col gap-2">
             <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold ${isOnline ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                {isOnline ? <Wifi size={14}/> : <WifiOff size={14}/>} {isOnline ? 'ONLINE' : 'OFFLINE'}
             </div>
             <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold ${locationStatus === 'verified' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                {locationStatus === 'checking' ? <Loader2 size={14} className="animate-spin" /> : <MapPin size={14}/>}
                {locationStatus === 'verified' ? 'LOKASI TERVERIFIKASI' : locationStatus === 'checking' ? 'CEK LOKASI...' : 'DI LUAR AREA'}
             </div>
          </div>
        </div>

        {isFormDisabled && (
            <div className="p-20 text-center flex flex-col items-center gap-4">
                <Lock size={48} className="text-slate-300" />
                <h3 className="text-xl font-bold text-slate-700">Formulir Terkunci</h3>
                <p className="text-slate-500 max-w-xs mx-auto">Anda harus terkoneksi internet dan berada di area store untuk mengisi laporan harian ini.</p>
                <button onClick={checkLocation} className="mt-4 px-6 py-2 bg-blue-600 text-white rounded-lg font-bold">Refresh Status</button>
            </div>
        )}

        {!isFormDisabled && (
          <div className="p-6 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-slate-700 mb-1">Shift</label>
                <select className="w-full p-3 border border-slate-300 rounded-lg outline-none" value={shift} onChange={(e) => setShift(e.target.value)}>
                  <option value="" disabled>-- Pilih Shift --</option>
                  <option value="Pagi">Shift Pagi</option>
                  <option value="Siang">Shift Siang</option>
                  <option value="Malam">Shift Malam</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Nama Anggota</label>
                <input type="text" className="w-full p-3 border border-slate-300 rounded-lg outline-none" placeholder="Nama Lengkap" value={inspectorName} onChange={(e) => setInspectorName(e.target.value)} />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">NIK</label>
                <input type="text" inputMode="numeric" className={`w-full p-3 border rounded-lg outline-none ${nikError ? 'border-red-500' : 'border-slate-300'}`} placeholder="NIK" value={nik} onChange={handleNikChange} />
              </div>
            </div>

            <div>
              <div className="flex items-center justify-between mb-4">
                 <h3 className="text-lg font-semibold text-slate-800">Item Ceklist</h3>
                 <div className="text-sm bg-blue-50 text-blue-700 px-3 py-1 rounded-full font-medium">Skor: {calculateScore()}%</div>
              </div>
              <div className="flex overflow-x-auto pb-2 mb-4 gap-2 no-scrollbar">
                {categories.map(cat => (
                  <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-4 py-2 rounded-full text-sm font-medium transition-colors ${activeCategory === cat ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-600'}`}>{cat}</button>
                ))}
              </div>
              <div className="space-y-3">
                {items.filter(i => i.category === activeCategory).map((item) => {
                  let isReadOnly = (shift === 'Siang' && item.category === 'PreOpening') || (shift === 'Malam' && (item.category === 'PreOpening' || item.category === 'Closing'));
                  return (
                    <div key={item.id} className={`p-4 rounded-lg border transition-colors ${isReadOnly ? 'bg-slate-100' : 'bg-slate-50'}`}>
                      <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                        <div className="flex-1">
                          <p className="font-medium text-slate-800">{item.label} {isReadOnly && <Lock size={12} className="inline text-slate-400" />}</p>
                          <div className="flex items-center gap-2 mt-2">
                            <input type="text" placeholder="Komentar..." className="flex-1 text-sm p-2 border rounded outline-none" value={item.comment || ''} onChange={(e) => handleCommentChange(item.id, e.target.value)} disabled={isReadOnly} />
                            {!item.photo ? (
                                <button onClick={() => startCamera({ type: 'checklist', itemId: item.id })} disabled={isReadOnly} className="p-2 rounded border text-slate-600"><Camera size={18} /></button>
                            ) : (
                                <img src={item.photo} alt="Bukti" className="w-10 h-10 object-cover rounded border" />
                            )}
                          </div>
                        </div>
                        <div className="flex gap-2">
                          {[InspectionStatus.PASS, InspectionStatus.FAIL, InspectionStatus.NA].map(status => (
                            <button key={status} onClick={() => handleStatusChange(item.id, status)} disabled={isReadOnly} className={`flex-1 py-2 px-3 rounded-lg text-sm font-bold border ${item.status === status ? 'bg-slate-800 text-white shadow-md' : 'bg-white text-slate-600 border-slate-200'}`}>
                              {status === InspectionStatus.PASS ? 'OK' : status === InspectionStatus.FAIL ? 'NO' : 'N/A'}
                            </button>
                          ))}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="border-t border-slate-200 pt-6">
              <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2"><AlertCircle className="text-amber-600" /> Observasi Lapangan</h3>
              <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-3">
                  <input type="text" placeholder="Lokasi" className="p-2 border border-slate-300 rounded outline-none" value={newObs.location} onChange={(e) => setNewObs({...newObs, location: e.target.value})} />
                  <select className="p-2 border border-slate-300 rounded outline-none" value={newObs.severity} onChange={(e) => setNewObs({...newObs, severity: e.target.value as any})}>
                    <option value="Low">Low</option><option value="Medium">Medium</option><option value="High">High</option><option value="Critical">Critical</option>
                  </select>
                </div>
                <textarea placeholder="Temuan..." className="w-full p-2 border border-slate-300 rounded h-20 mb-3" value={newObs.description} onChange={(e) => setNewObs({...newObs, description: e.target.value})} />
                <div className="mb-3">
                  {tempObsImage ? (
                    <img src={tempObsImage} alt="Captured" className="h-20 rounded border" />
                  ) : (
                    <button onClick={() => startCamera({ type: 'observation' })} className="flex items-center gap-2 px-4 py-2 bg-slate-200 rounded-lg text-sm"><Camera size={16} /> Foto</button>
                  )}
                </div>
                <button onClick={addObservation} disabled={!newObs.description} className="bg-slate-800 text-white px-4 py-2 rounded-lg text-sm w-full">Tambah Observasi</button>
              </div>
            </div>
          </div>
        )}

        <div className="bg-slate-50 p-6 border-t border-slate-200 flex justify-end gap-3">
          <button onClick={onCancel} className="px-6 py-2 rounded-lg border border-slate-300">Batal</button>
          <button onClick={handleSubmit} disabled={isGenerating || isFormDisabled} className="px-6 py-2 rounded-lg bg-blue-600 text-white font-medium flex items-center gap-2 disabled:opacity-50">
            {isGenerating ? <><Loader2 size={18} className="animate-spin" /> Menganalisa...</> : <><Save size={18} /> Simpan & Analisa AI</>}
          </button>
        </div>
      </div>
    </div>
  );
};

export default InspectionForm;

import React, { useState, useEffect } from 'react';
import { Tab, DailyReport } from './types';
import Dashboard from './components/Dashboard';
import InspectionForm from './components/InspectionForm';
import ReportHistory from './components/ReportHistory';
import { getReports, saveReport } from './services/storageService';
import { LayoutDashboard, ClipboardCheck, History, ShieldCheck } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [reports, setReports] = useState<DailyReport[]>([]);
  const [isFormDirty, setIsFormDirty] = useState(false);

  useEffect(() => {
    setReports(getReports());
  }, []);

  // Proteksi menutup tab browser atau refresh
  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (isFormDirty && activeTab === 'inspect') {
        const message = "Data yang Anda masukkan belum disimpan. Apakah Anda yakin ingin keluar?";
        e.returnValue = message;
        return message;
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [isFormDirty, activeTab]);

  const handleTabChange = (newTab: Tab) => {
    if (activeTab === 'inspect' && isFormDirty && newTab !== 'inspect') {
      const confirmLeave = window.confirm("Ada perubahan yang belum disimpan. Tinggalkan halaman formulir?");
      if (!confirmLeave) return;
    }

    // Reset dirty state saat pindah tab (jika user setuju leave)
    if (activeTab === 'inspect' && newTab !== 'inspect') {
        setIsFormDirty(false);
    }

    setActiveTab(newTab);
  };

  const handleSaveReport = (report: DailyReport) => {
    saveReport(report);
    setReports(getReports());
    setIsFormDirty(false); // Reset dirty state setelah berhasil simpan
    setActiveTab('history');
  };

  const handleCancelInspect = () => {
    if (isFormDirty) {
        const confirmLeave = window.confirm("Batalkan pengisian formulir? Data yang sudah diisi akan hilang.");
        if (!confirmLeave) return;
    }
    setIsFormDirty(false);
    setActiveTab('dashboard');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard reports={reports} onCreateNew={() => handleTabChange('inspect')} />;
      case 'inspect':
        return (
          <InspectionForm 
            onSave={handleSaveReport} 
            onCancel={handleCancelInspect} 
            existingReports={reports}
            onDirtyChange={setIsFormDirty}
          />
        );
      case 'history':
        return <ReportHistory reports={reports} />;
      default:
        return <Dashboard reports={reports} onCreateNew={() => handleTabChange('inspect')} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">
      {/* Top Navbar */}
      <nav className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 text-blue-700">
            <ShieldCheck size={28} />
            <span className="text-xl font-bold tracking-tight">LOSS PREVENTION DEPARTMENT</span>
          </div>
          <div className="text-sm text-slate-500 hidden sm:block">
            Operasional Harian & Keamanan
          </div>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="max-w-5xl mx-auto p-4 sm:p-6">
        {renderContent()}
      </main>

      {/* Bottom Mobile/Tablet Navigation */}
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 py-2 px-6 flex justify-around items-center sm:hidden shadow-lg z-50">
        <button 
          onClick={() => handleTabChange('dashboard')}
          className={`flex flex-col items-center gap-1 text-xs font-medium ${activeTab === 'dashboard' ? 'text-blue-600' : 'text-slate-400'}`}
        >
          <LayoutDashboard size={24} />
          Dasbor
        </button>
        <button 
          onClick={() => handleTabChange('inspect')}
          className={`flex flex-col items-center gap-1 text-xs font-medium ${activeTab === 'inspect' ? 'text-blue-600' : 'text-slate-400'}`}
        >
