      {/* Desktop Sidebar/Tabs */}
      <div className="hidden sm:flex fixed bottom-8 left-1/2 transform -translate-x-1/2 bg-white px-2 py-2 rounded-full shadow-xl border border-slate-200 z-40 gap-1">
         <button 
            onClick={() => handleTabChange('dashboard')}
            className={`px-6 py-2 rounded-full text-sm font-semibold transition-all ${activeTab === 'dashboard' ? 'bg-slate-800 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
         >
           Dasbor
         </button>
         <button 
            onClick={() => handleTabChange('inspect')}
            className={`px-6 py-2 rounded-full text-sm font-semibold transition-all ${activeTab === 'inspect' ? 'bg-slate-800 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
         >
           Inspeksi Baru
         </button>
         <button 
            onClick={() => handleTabChange('history')}
            className={`px-6 py-2 rounded-full text-sm font-semibold transition-all ${activeTab === 'history' ? 'bg-slate-800 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
         >
           Riwayat
         </button>
      </div>

    </div>
  );
};

